# Generated by the network debugging agent
# Request: check if DNS resolution works for web.lab
# TYPE: one-sided
# Re-run: python tool_builder.py --run tools/dns_web_lab.py
#!/usr/bin/env python3
"""Check if DNS resolution works for web.lab (one-sided, runs in ns1 only)."""
import concurrent.futures
import socket
import subprocess
import sys
import time
import os

TARGET = "web.lab"
DIG_TIMEOUT = 4
NATIVE_TIMEOUT = 5

# Ensure any socket created without explicit timeout still times out quickly
socket.setdefaulttimeout(5)


def run_cmd(argv, timeout=DIG_TIMEOUT):
    """Run command via subprocess with timeout, return (returncode, stdout, stderr, elapsed, timed_out)."""
    start = time.monotonic()
    try:
        cp = subprocess.run(
            argv,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
        elapsed = time.monotonic() - start
        return cp.returncode, cp.stdout, cp.stderr, elapsed, False
    except subprocess.TimeoutExpired as e:
        elapsed = time.monotonic() - start
        out = (e.stdout.decode() if isinstance(e.stdout, bytes) else (e.stdout or ""))
        err = (e.stderr.decode() if isinstance(e.stderr, bytes) else (e.stderr or ""))
        return None, out, err + f"\n[TIMEOUT after {timeout}s]", elapsed, True
    except FileNotFoundError as e:
        elapsed = time.monotonic() - start
        return None, "", f"command not found: {e}", elapsed, False
    except OSError as e:
        elapsed = time.monotonic() - start
        return None, "", f"OS error: {e}", elapsed, False


def native_resolve(host, timeout=NATIVE_TIMEOUT):
    """Resolve via Python stdlib getaddrinfo with a hard timeout. Returns (ok, addrs, elapsed, error)."""
    start = time.monotonic()
    try:
        with concurrent.futures.ThreadPoolExecutor(max_workers=1) as ex:
            fut = ex.submit(socket.getaddrinfo, host, 80, socket.AF_UNSPEC, socket.SOCK_STREAM)
            infos = fut.result(timeout=timeout)
        elapsed = time.monotonic() - start
        addrs = sorted(set(info[4][0] for info in infos))
        return True, addrs, elapsed, "", infos
    except concurrent.futures.TimeoutError:
        elapsed = time.monotonic() - start
        return False, [], elapsed, f"getaddrinfo timed out after {timeout}s", []
    except socket.gaierror as e:
        elapsed = time.monotonic() - start
        return False, [], elapsed, f"gaierror: {e}", []
    except OSError as e:
        elapsed = time.monotonic() - start
        return False, [], elapsed, f"OSError: {e}", []


def main():
    print("=== DNS resolution test for web.lab ===")
    print(f"TARGET: {TARGET}")
    print(f"HOST: {socket.gethostname()}  PID: {os.getpid()}")
    try:
        print(f"LOCAL IP check: {socket.gethostbyname(socket.gethostname())}")
    except Exception as e:
        print(f"LOCAL IP check: failed ({e})")

    # 1. Show resolver config (evidence)
    print("\n--- [INFO] /etc/resolv.conf ---")
    try:
        with open("/etc/resolv.conf", "r") as f:
            resolv = f.read()
        print(resolv.strip() if resolv.strip() else "(empty)")
    except OSError as e:
        print(f"could not read /etc/resolv.conf: {e}")
        resolv = ""

    # 2. Native Python resolution
    print("\n--- [TEST 1] Native resolution via socket.getaddrinfo ---")
    ok_native, addrs, t_native, err_native, infos = native_resolve(TARGET, timeout=NATIVE_TIMEOUT)
    print(f"timing: {t_native:.3f}s  timeout={NATIVE_TIMEOUT}s")
    if ok_native:
        print(f"[RESULT] native resolution: SUCCESS -> {', '.join(addrs)}")
        print("[EVIDENCE] raw getaddrinfo:")
        for info in infos:
            print(f"  family={info[0]} type={info[1]} proto={info[2]} canon={info[3]} sockaddr={info[4]}")
    else:
        print(f"[RESULT] native resolution: FAIL -> {err_native}")
        print(f"[EVIDENCE] error string: {err_native}")

    # 3. dig full output (evidence)
    print("\n--- [TEST 2] dig web.lab (system resolver) ---")
    rc, out, err, elapsed, timed_out = run_cmd(["dig", TARGET], timeout=DIG_TIMEOUT)
    print(f"timing: {elapsed:.3f}s  timeout={DIG_TIMEOUT}s  timed_out={timed_out}  returncode={rc}")
    print("[EVIDENCE] stdout:")
    print(out.strip() if out.strip() else "(empty stdout)")
    print("[EVIDENCE] stderr:")
    print(err.strip() if err.strip() else "(empty stderr)")

    # 4. dig +short (easy parse)
    print("\n--- [TEST 3] dig +short web.lab ---")
    rc2, out2, err2, elapsed2, timed_out2 = run_cmd(["dig", "+short", TARGET], timeout=DIG_TIMEOUT)
    print(f"timing: {elapsed2:.3f}s  timeout={DIG_TIMEOUT}s  timed_out={timed_out2}  returncode={rc2}")
    print("[EVIDENCE] stdout:")
    print(out2.strip() if out2.strip() else "(empty stdout)")
    print("[EVIDENCE] stderr:")
    print(err2.strip() if err2.strip() else "(empty stderr)")
    short_answers = [l.strip() for l in out2.strip().splitlines() if l.strip()] if out2 else []
    print(f"[RESULT] dig +short answers: {short_answers if short_answers else 'NONE'}")

    # 5. dig explicitly via 10.0.0.2 (expected DNS server from lab)
    print("\n--- [TEST 4] dig @10.0.0.2 web.lab (explicit lab DNS) ---")
    rc3, out3, err3, elapsed3, timed_out3 = run_cmd(["dig", "@10.0.0.2", TARGET], timeout=DIG_TIMEOUT)
    print(f"timing: {elapsed3:.3f}s  timeout={DIG_TIMEOUT}s  timed_out={timed_out3}  returncode={rc3}")
    print("[EVIDENCE] stdout:")
    print(out3.strip() if out3.strip() else "(empty stdout)")
    print("[EVIDENCE] stderr:")
    print(err3.strip() if err3.strip() else "(empty stderr)")

    # Summary verdict
    print("\n=== SUMMARY ===")
    success = ok_native or len(short_answers) > 0
    # Also consider explicit dig output containing an A record
    if not success and out3 and "NOERROR" in out3 and "ANSWER:" in out3:
        # crude check for answer section non-zero
        success = "ANSWER: 0" not in out3
    if success:
        print(f"[FINAL] PASS: {TARGET} resolves (native_ok={ok_native}, dig_short={short_answers})")
    else:
        print(f"[FINAL] FAIL: {TARGET} does NOT resolve (native_ok={ok_native}, dig_short={short_answers})")
        print("[HINT] Check /etc/resolv.conf nameserver, dig status (NXDOMAIN vs SERVFAIL vs timeout).")
        if timed_out or timed_out2 or timed_out3:
            print("[HINT] At least one dig timed out -> DNS server unreachable or firewall.")
        if out and ("NXDOMAIN" in out or "NXDOMAIN" in out3):
            print("[HINT] NXDOMAIN means DNS server reachable but name does not exist.")
        if out and ("SERVFAIL" in out or "SERVFAIL" in out3):
            print("[HINT] SERVFAIL means server failure / misconfiguration.")

    print("Test completed (exit 0).")
    sys.exit(0)


if __name__ == "__main__":
    main()
